<body>
  <div class="card">
    <h1>
      🧠 Workshop: Build & Grow
      <span class="badge">20 seats</span>
    </h1>
    <div class="subhead">
      Reserve your spot — just name and email. Once we reach 20, signup closes.
    </div>

    <!-- seat counter -->
    <div class="seat-meter">
      <div class="seats-left">
        <span id="seatsLeftDisplay">20</span>
        <span>seats left</span>
      </div>
      <div class="capacity" id="capacityDisplay">0 / 20 filled</div>
    </div>

    <!-- signup form -->
    <form id="signupForm" autocomplete="off">
      <div class="form-group">
        <label for="nameInput">👤 Full name</label>
        <input type="text" id="nameInput" placeholder="e.g. Jamie Chen" required>
      </div>
      <div class="form-group">
        <label for="emailInput">✉️ Email address</label>
        <input type="email" id="emailInput" placeholder="jamie@example.com" required>
      </div>
      <button type="submit" class="btn" id="submitBtn">
        🎟️ Reserve my seat
      </button>
    </form>

    <!-- feedback message -->
    <div class="message-area" id="messageArea">
      ⏳ Fill the form to grab a seat.
    </div>

    <!-- attendee list -->
    <div class="attendee-section">
      <div class="attendee-header">
        <h2>📋 Who's coming</h2>
        <button class="btn-outline" id="resetBtn" title="Reset all signups (demo)">Reset</button>
      </div>
      <ul class="attendee-list" id="attendeeList">
        <li class="empty-note">No one has signed up yet — be the first!</li>
      </ul>
    </div>
    <div class="small-note">
      * Demo only — data is stored in memory.
    </div>
  </div>

  <script>
    (function() {
      // ---------- STATE ----------
      const MAX_SEATS = 20;
      let attendees = [];                // array of { name, email }

      // DOM elements
      const form = document.getElementById('signupForm');
      const nameInput = document.getElementById('nameInput');
      const emailInput = document.getElementById('emailInput');
      const submitBtn = document.getElementById('submitBtn');
      const seatsLeftSpan = document.getElementById('seatsLeftDisplay');
      const capacityDisplay = document.getElementById('capacityDisplay');
      const messageArea = document.getElementById('messageArea');
      const attendeeListEl = document.getElementById('attendeeList');
      const resetBtn = document.getElementById('resetBtn');

      // Helper: update UI (counter, list, button/input states)
      function renderUI() {
        const seatsLeft = MAX_SEATS - attendees.length;
        const totalFilled = attendees.length;

        // update counters
        seatsLeftSpan.textContent = seatsLeft;
        capacityDisplay.textContent = `${totalFilled} / ${MAX_SEATS} filled`;

        // enable/disable form & button when full
        const isFull = seatsLeft === 0;
        if (isFull) {
          nameInput.disabled = true;
          emailInput.disabled = true;
          submitBtn.disabled = true;
          // optionally add visual style via class
          nameInput.classList.add('disabled-input');
          emailInput.classList.add('disabled-input');
        } else {
          nameInput.disabled = false;
          emailInput.disabled = false;
          submitBtn.disabled = false;
          nameInput.classList.remove('disabled-input');
          emailInput.classList.remove('disabled-input');
        }

        // ----- RENDER ATTENDEE LIST -----
        attendeeListEl.innerHTML = '';   // clear

        if (attendees.length === 0) {
          const emptyItem = document.createElement('li');
          emptyItem.className = 'empty-note';
          emptyItem.textContent = 'No one has signed up yet — be the first!';
          attendeeListEl.appendChild(emptyItem);
          return;
        }

        // show attendees in reverse order (newest first) for convenience
        const reversed = [...attendees].reverse();
        reversed.forEach((person, index) => {
          // original index for seat number (since we reversed, calculate: attendees.length - index)
          const seatIndex = attendees.length - index;
          const li = document.createElement('li');

          const infoDiv = document.createElement('div');
          infoDiv.className = 'attendee-info';

          const nameSpan = document.createElement('span');
          nameSpan.className = 'attendee-name';
          nameSpan.textContent = person.name;

          const emailSpan = document.createElement('span');
          emailSpan.className = 'attendee-email';
          emailSpan.textContent = person.email;

          infoDiv.appendChild(nameSpan);
          infoDiv.appendChild(emailSpan);

          const seatBadge = document.createElement('span');
          seatBadge.className = 'seat-number';
          seatBadge.textContent = `#${seatIndex}`;

          li.appendChild(infoDiv);
          li.appendChild(seatBadge);
          attendeeListEl.appendChild(li);
        });
      }

      // Helper: show message
      function setMessage(text, type = 'neutral') {
        messageArea.textContent = text;
        messageArea.classList.remove('success-msg', 'error-msg');
        if (type === 'success') {
          messageArea.classList.add('success-msg');
        } else if (type === 'error') {
          messageArea.classList.add('error-msg');
        }
      }

      // Validate email format (simple)
      function isValidEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      }

      // Check if email already exists
      function emailExists(email) {
        return attendees.some(p => p.email.toLowerCase() === email.toLowerCase());
      }

      // Add attendee (core logic)
      function addAttendee(name, email) {
        // trim
        const trimmedName = name.trim();
        const trimmedEmail = email.trim().toLowerCase(); // store lower for consistency?

        // validations
        if (!trimmedName) {
          setMessage('❌ Please enter your full name.', 'error');
          return false;
        }
        if (!trimmedEmail) {
          setMessage('❌ Please enter your email address.', 'error');
          return false;
        }
        if (!isValidEmail(trimmedEmail)) {
          setMessage('❌ Please enter a valid email address.', 'error');
          return false;
        }
        if (emailExists(trimmedEmail)) {
          setMessage(`❌ ${trimmedEmail} is already registered.`, 'error');
          return false;
        }
        if (attendees.length >= MAX_SEATS) {
          setMessage('⚠️ Workshop is full. No more seats available.', 'error');
          return false;
        }

        // Add attendee
        attendees.push({
          name: trimmedName,
          email: trimmedEmail
        });

        // Success feedback
        setMessage(`✅ Seat reserved for ${trimmedName}! Confirmation sent to ${trimmedEmail} (demo).`, 'success');

        // Clear form fields
        nameInput.value = '';
        emailInput.value = '';

        // focus name field for next entry
        nameInput.focus();

        // Update UI
        renderUI();

        // If just filled the last seat, message adjust
        if (attendees.length === MAX_SEATS) {
          setMessage('🎉 Workshop is now full! No more seats available.', 'success');
        }
        return true;
      }

      // ---------- EVENT LISTENERS ----------
      form.addEventListener('submit', function(e) {
        e.preventDefault();

        // Double-check if full (extra guard)
        if (attendees.length >= MAX_SEATS) {
          setMessage('⛔ All seats are taken. Signup is closed.', 'error');
          renderUI(); // refresh disabled state if not already
          return;
        }

        const name = nameInput.value;
        const email = emailInput.value;

        addAttendee(name, email);
      });

      // Reset button (demo)
      resetBtn.addEventListener('click', function() {
        if (attendees.length > 0) {
          if (confirm('Reset all signups? This cannot be undone.')) {
            attendees = [];
            nameInput.value = '';
            emailInput.value = '';
            setMessage('✨ All seats are available again.', 'success');
            renderUI();
            // ensure inputs enabled
            nameInput.disabled = false;
            emailInput.disabled = false;
            submitBtn.disabled = false;
            nameInput.classList.remove('disabled-input');
            emailInput.classList.remove('disabled-input');
            nameInput.focus();
          }
        } else {
          setMessage('Nothing to reset — no signups yet.', 'neutral');
        }
      });

      // If user focuses on disabled fields, nothing happens (they are disabled). fine.

      // Initial render
      renderUI();

      // Set a friendly initial message
      setMessage('⏳ Fill the form to grab a seat. 20 available!', 'neutral');

      // When the page loads, focus on name (if not full)
      window.addEventListener('load', function() {
        if (attendees.length < MAX_SEATS) {
          nameInput.focus();
        }
      });

      // Optional: if full, disable from start? (already handled via renderUI)
      // but also re-check if initial state is full (should not be, but for safety)
      // (renderUI at bottom already sets it)
    })();
  </script>
</body>
</html>
```
### How the Workshop Signup Works
This page makes it easy for people to claim one of the 20 available spots. You can see the live seat count, register with a name and email, and view the growing list of attendees.

*   **Seat Availability:** A live counter shows the number of seats left and how many are filled. The form and submit button automatically disable once all 20 seats are taken.
*   **Registration Form:** You must enter a name and a valid email address. The system checks for empty fields, invalid emails, and duplicate email addresses before confirming a seat.
*   **Attendee List:** The list updates instantly after a successful signup, showing each person's name, email, and their assigned seat number. A "Reset" button lets you clear all signups for demonstration purposes.

---

**Optimization Tip:** You can change the `MAX_SEATS` variable (line 143) to a different number to adjust the workshop capacity. The attendee data is stored in the `attendees` array (line 142).

