    .attendee-list li {
      background: #f5faff;
      padding: 0.9rem 1.2rem;
      border-radius: 60px;
      border: 1px solid #d9e6ee;
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 0.98rem;
