    @media (max-width: 540px) {
      .card { padding: 1.8rem 1.3rem; }
      h1 { font-size: 1.7rem; flex-wrap: wrap; }
      .badge { margin-left: 0; }
      .attendee-list li { padding: 0.7rem 1rem; }
